pm.test("Status code is 201 Created", function () {
    pm.response.to.have.status(201);
});

pm.test("Content-Type header is application/json", function () {
    pm.response.to.have.header("content-type", "application/json");
});

pm.test("Response contains valid post object", function () {
    const responseData = pm.response.json();
    pm.expect(responseData.message).to.eql("Post created successfully");

    pm.expect(responseData).to.have.property("post");
    const post = responseData.post;

    pm.expect(post).to.have.property("id").that.is.a("number");
    pm.expect(post.title).to.eql("Welcome to the Forum!");
    pm.expect(post.content).to.eql("This is my very first post on this forum.");
    pm.expect(post.author).to.eql("John");

    pm.expect(post).to.have.property("created_at");
    pm.expect(post).to.have.property("updated_at");
});

pm.test("Save created post ID as a collection variable", function () {
    const responseData = pm.response.json();
    if (responseData.post && responseData.post.id) {
        pm.collectionVariables.set("postId", responseData.post.id);
        console.log("Saved postId variable:", responseData.post.id);
    }
});

